def tr(key: str, default: str = None):
    try:
        lang = mw.pm.profile.get('onigiri_language', 'en')
    except:
        lang = 'en'
    if lang not in TRANSLATIONS:
        lang = 'en'
    return TRANSLATIONS[lang].get(key, TRANSLATIONS['en'].get(key, default or key))


def render_html_strings(html: str) -> str:
    """Replaces %%T:key%% markers in a static dialog page with translated text.

    The static pages under web/ (birthday, credits, donations) have no bridge to
    the settings, so their copy is substituted here before the webview sees it."""
    import html as _html
    import re

    def _sub(match):
        return _html.escape(tr(match.group(1)), quote=False)

    return re.sub(r"%%T:([A-Za-z0-9_]+)%%", _sub, html)


def current_language() -> str:
    try:
        lang = mw.pm.profile.get('onigiri_language', 'en')
    except Exception:
        lang = 'en'
    return lang if lang in TRANSLATIONS else 'en'


def current_locale():
    """QLocale matching the add-on's configured language (not the OS locale),
    so weekday/month names line up with the rest of the translated UI."""
    from PyQt6.QtCore import QLocale
    return QLocale(current_language())


